import{_ as t,o as s,c as n,ah as r}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Personnel et comptes utilisateurs","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/personnel-utilisateurs.md","filePath":"src/guide/admin/personnel-utilisateurs.md"}'),i={name:"guide/admin/personnel-utilisateurs.md"};function o(a,e,l,u,d,c){return s(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="personnel-et-comptes-utilisateurs" tabindex="-1">Personnel et comptes utilisateurs <a class="header-anchor" href="#personnel-et-comptes-utilisateurs" aria-label="Permalink to &quot;Personnel et comptes utilisateurs&quot;">​</a></h1><p>Cette section couvre deux choses distinctes qu&#39;il ne faut pas confondre : le <strong>compte utilisateur</strong> (identifiants de connexion + rôle, dans <strong>Utilisateurs</strong>) et la <strong>fiche employé</strong> (poste, site, contrats, dans la groupe <strong>Personnel</strong>). Un enseignant, par exemple, a besoin des deux — un compte pour se connecter, une fiche pour son poste et ses contrats — mais ce sont deux écrans séparés.</p><h2 id="creer-un-compte-utilisateur-et-lui-assigner-un-role" tabindex="-1">Créer un compte utilisateur et lui assigner un rôle <a class="header-anchor" href="#creer-un-compte-utilisateur-et-lui-assigner-un-role" aria-label="Permalink to &quot;Créer un compte utilisateur et lui assigner un rôle&quot;">​</a></h2><p><strong>Utilisateurs</strong> (groupe <strong>Administration</strong> du menu) liste tous les comptes de l&#39;établissement, avec une recherche par nom/e-mail, un filtre par rôle, et le statut vérifié/non vérifié et actif/inactif de chacun.</p><p>Pour créer un utilisateur :</p><ol><li>Cliquez sur <strong>Nouvel utilisateur</strong>.</li><li>Renseignez le <strong>Nom</strong>, l&#39;<strong>Adresse e-mail</strong>, le <strong>Mot de passe</strong> et sa confirmation.</li><li>Choisissez le <strong>Rôle</strong> : Utilisateur, Administrateur, Enseignant, Secrétariat, Caisse, Vie scolaire, Gestionnaire internat, Infirmerie ou Gestionnaire documentaire — et, si l&#39;établissement a le module Pilotage, <strong>Direction de site</strong> ou <strong>Direction générale</strong>.</li><li>Pour une <strong>Direction de site</strong>, cochez le ou les <strong>Sites dirigés</strong> (au moins un).</li><li>Cliquez sur <strong>Créer l&#39;utilisateur</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Les profils de direction</p><p>Ils vont à ceux qui dirigent sans saisir : directeur de campus, chef d&#39;établissement. Ils voient les demandes à valider de leurs sites, pas les écrans opérationnels. Un compte n&#39;a qu&#39;un rôle : si le chef d&#39;établissement administre aussi l&#39;application, laissez-le Administrateur, qui peut déjà tout valider. Voir <a href="/era-guide/guide/direction/">Direction</a>.</p></div><p>Depuis la liste, chaque compte propose :</p><ul><li><strong>Modifier</strong> — changer le nom, l&#39;e-mail, le rôle, ou définir un nouveau mot de passe (laissez le champ vide pour conserver l&#39;actuel).</li><li><strong>Activer</strong> / <strong>Désactiver</strong> — désactiver un compte le déconnecte immédiatement partout et bloque toute nouvelle connexion, sans supprimer le compte ; le réactiver restaure l&#39;accès.</li><li><strong>Supprimer</strong> — définitif et irréversible.</li><li><strong>Exporter en CSV</strong> (en haut de la page) — exporte la liste filtrée actuelle.</li></ul><h2 id="gerer-les-fiches-et-contrats-du-personnel" tabindex="-1">Gérer les fiches et contrats du personnel <a class="header-anchor" href="#gerer-les-fiches-et-contrats-du-personnel" aria-label="Permalink to &quot;Gérer les fiches et contrats du personnel&quot;">​</a></h2><p>La page <strong>Employés</strong> (groupe <strong>Personnel</strong>) liste les fiches employé — poste, site, date d&#39;embauche et statut — distinctes des comptes utilisateurs.</p><p>Pour créer une fiche employé :</p><ol><li>Cliquez sur <strong>Nouvel employé</strong>.</li><li>Renseignez les champs de la section « Personne » ci-dessous.</li><li>Renseignez les champs de la section « Affectation » ci-dessous.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>Section « Personne » :</p><table tabindex="0"><thead><tr><th>Champ</th><th>Détail</th></tr></thead><tbody><tr><td>Compte du personnel</td><td>choisi parmi les comptes utilisateurs existants</td></tr><tr><td>Poste</td><td>intitulé libre</td></tr></tbody></table><p>Section « Affectation » :</p><table tabindex="0"><thead><tr><th>Champ</th><th>Détail</th></tr></thead><tbody><tr><td>Site</td><td>laissez « Non affecté » si besoin</td></tr><tr><td>Date d&#39;embauche</td><td>—</td></tr><tr><td>Statut</td><td>Actif ou Inactif</td></tr></tbody></table><p>Supprimer une fiche employé supprime aussi définitivement ses contrats.</p><h3 id="contrats" tabindex="-1">Contrats <a class="header-anchor" href="#contrats" aria-label="Permalink to &quot;Contrats&quot;">​</a></h3><p>Depuis la fiche d&#39;un employé (bouton <strong>Modifier</strong> dans la liste), la section <strong>Contrats</strong> liste ses contrats et permet d&#39;en ajouter un :</p><ol><li>Cliquez sur <strong>Nouveau contrat</strong>.</li><li>Renseignez le <strong>Type</strong> (CDI, CDD ou Stage), la <strong>Date de début</strong>, la <strong>Date de fin</strong> (facultative), un <strong>Document</strong> à téléverser (PDF, JPG ou PNG) et des <strong>Notes</strong> libres.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>Chaque contrat listé propose ensuite <strong>Voir le document</strong> (s&#39;il y en a un) et <strong>Supprimer</strong> (définitif, supprime aussi le document).</p><h2 id="affecter-les-enseignants-a-des-classes-et-des-matieres" tabindex="-1">Affecter les enseignants à des classes et des matières <a class="header-anchor" href="#affecter-les-enseignants-a-des-classes-et-des-matieres" aria-label="Permalink to &quot;Affecter les enseignants à des classes et des matières&quot;">​</a></h2><p><strong>Paramétrage scolaire → Affectations enseignants</strong> est ce qui autorise un enseignant à saisir des notes ou des observations pour une classe donnée : sans affectation, il n&#39;a accès à rien.</p><p>Pour créer une affectation :</p><ol><li>Cliquez sur <strong>Nouvelle affectation</strong>.</li><li>Choisissez l&#39;<strong>Enseignant</strong> puis la <strong>Classe</strong>.</li><li>Si la classe appartient à un département qualitatif (crèche/maternelle, notation par compétences), le champ <strong>Matière</strong> disparaît — l&#39;enseignant est affecté à toute la classe. Sinon, choisissez la <strong>Matière</strong> enseignée.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>Une affectation supprimée retire immédiatement à l&#39;enseignant l&#39;accès à la saisie des notes correspondante.</p><h2 id="traiter-une-mutation-de-personnel-entre-sites" tabindex="-1">Traiter une mutation de personnel entre sites <a class="header-anchor" href="#traiter-une-mutation-de-personnel-entre-sites" aria-label="Permalink to &quot;Traiter une mutation de personnel entre sites&quot;">​</a></h2><p>Une mutation de personnel déplace un employé d&#39;un site vers un autre, une fois la demande approuvée.</p><p><strong>Demander une mutation</strong> (depuis la fiche de l&#39;employé, section « Mutation de site ») :</p><ol><li>Cliquez sur <strong>Demander une mutation</strong>.</li><li>Choisissez le <strong>Site de destination</strong> et indiquez un <strong>Motif</strong>.</li><li>Cliquez sur <strong>Soumettre la demande</strong>.</li></ol><p>Sont alors notifiés les autres administrateurs, la direction générale et la direction de chacun des deux sites. Chacun d&#39;eux peut décider ; la première décision clôt la demande. Rien n&#39;empêche l&#39;administrateur qui a soumis la demande de l&#39;approuver lui-même.</p><p><strong>Examiner une demande</strong> — section <strong>Personnel → Mutations de personnel</strong> liste les demandes, avec un filtre par statut (En attente, Approuvé, Refusé). Ouvrez une demande via <strong>Examiner</strong> pour voir l&#39;employé, les sites d&#39;origine et de destination, le motif, puis :</p><ul><li><strong>Approuver</strong> — applique le transfert.</li><li><strong>Refuser</strong> — ouvre une boîte de dialogue demandant un motif de refus obligatoire.</li></ul><p>Une demande peut aussi être traitée depuis la notification reçue, qui ouvre la page <a href="/era-guide/guide/direction/a-approuver.html">À approuver</a> avec les mêmes actions <strong>Approuver</strong> / <strong>Refuser</strong>.</p>',35)])])}const m=t(i,[["render",o]]);export{g as __pageData,m as default};
